/* Kimya Koçum · Sanal Lab · Kitabın deney soruları (MEB, birebir) + ek sorular. labkit.js ve titrasyon.html kullanır. */
(function(){
const D={"evdeph":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 21 · Değerlendirme","kitap":[{"q":"Deney tüplerine saf su ilave edildiğinde maddelerin pH değeri nasıl değişti?","c":"Asidik maddelerin (limon tuzu, sirke, gazlı içecek) pH değeri arttı, 7’ye yaklaştı. Bazik maddelerin (karbonat, sabun, diş macunu, antiasit) pH değeri azaldı, yine 7’ye yaklaştı. Seyreltme her iki durumda da çözeltiyi nötre doğru götürür."},{"q":"Diş macununun pH değeri saf su eklendiğinde nasıl değişti? Bazik özelliği arttı mı yoksa azaldı mı? Deneydeki verilerden yola çıkarak “Diş fırçanızı ıslatmayın!” uyarısının nedenini açıklayınız.","c":"pH değeri düştü, yani bazik özelliği azaldı. Fırça ıslatılınca macun seyrelir; bazikliği ve dolayısıyla ağızdaki asitleri nötrleştirme etkisi azalır. Bu yüzden fırçanın ıslatılmaması önerilir."},{"q":"Antiasit tabletler mide yanmasını gidermek için kullanılan çiğneme tabletleridir. Antiasit tabletler asidik mi yoksa bazik midir? Antiasit tabletlerin pH değeri su eklendiğinde nasıl değişti? Bu tabletlerin çiğneme tableti olmasını ve su ile içilmemesinin nedenini deney sonuçlarından elde ettiğiniz verileri kullanarak nasıl açıklarsınız?","c":"Antiasitler baziktir. Su eklenince pH değeri düştü, bazikliği azaldı. Tablet su ile içilirse seyrelir ve mide asidini nötrleştirme gücü azalır. Çiğnenerek derişik hâlde mideye ulaşması bu yüzden daha etkilidir."},{"q":"Çaydanlıkta biriken kireci (kalsiyum karbonat) çözmek için limon tuzunun tercih edilme nedenini açıklayınız? Günlük hayatta kullandığınız ve içerisine kireç biriken kapların kirecini gidermek için limon tuzu dışında başka hangi maddeler kullanılabilir?","c":"Limon tuzu (sitrik asit) asidiktir. Bazik karakterli kalsiyum karbonatla tepkimeye girerek suda çözünen ürünler ve CO₂ oluşturur, kireç çözülür. Sirke, limon suyu ve ticari kireç çözücüler de kullanılabilir."},{"q":"Limon tuzunun mermer mutfak tezgâhına ve tebeşire yaptığı etki ile karbonatın bu maddelere etkisi aynı olur mu? Neden?","c":"Hayır. Mermer ve tebeşir kalsiyum karbonattır. Limon tuzu asidik olduğu için onlarla tepkimeye girip yüzeyi aşındırır. Karbonat (NaHCO₃) bazik olduğu için onlarla tepkimeye girmez."},{"q":"Gazlı içeceklerin pas temizleme işleminde kullanılma nedenini açıklayınız. Paslanmış metalleri temizlemek için gazlı içecekler dışında hangi maddeler kullanılabilir?","c":"Gazlı içecekler asidiktir (karbonik asit, fosforik asit). Asit, pası (demir oksit) çözer. Sirke, limon suyu ve limon tuzu da kullanılabilir."}],"ek":[{"q":"pH kâğıdı koyu mavi renk aldıysa madde için ne söylenebilir?","s":["Kuvvetli asidiktir","Nötrdür","Baziktir","Tuzdur"],"d":2,"a":"pH skalasında yeşilden maviye doğru gidildikçe bazlık artar. Koyu mavi, pH 10 ve üzeri bazik bir maddeyi gösterir."},{"q":"Asidik bir çözeltiye bol miktarda saf su eklenirse pH değeri için hangisi doğrudur?","s":["7’nin üstüne çıkar","7’ye yaklaşır ama 7’yi geçmez","Değişmez","0’a iner"],"d":1,"a":"Seyreltme H⁺ derişimini azaltır, pH artar. Ancak su eklemekle asit baza dönüşmez, pH 7’yi geçmez."},{"q":"Deneyde pH ölçümü için her madde neden ayrı bir tüpe konulur ve tüpler etiketlenir?","s":["Tepkime hızını artırmak için","Maddeler birbirine karışıp ölçüm bozulmasın ve sonuçlar karışmasın diye","pH kâğıdı daha az harcansın diye","Maddeler buharlaşmasın diye"],"d":1,"a":"Her ölçüm yalnız bir maddeye ait olmalıdır. Karışan maddeler tepkimeye girip pH değerini değiştirebilir. Etiket de verilerin doğru kaydedilmesini sağlar."}]},"folyo":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 23 · Değerlendirme","kitap":[{"q":"Deneyden elde ettiğiniz verilere dayanarak sonuçlarınızı özetleyiniz.","c":"Folyonun mat tarafı dışa bakarken su daha hızlı ısındı. Parlak yüzey ışınımı daha çok yansıtır, mat yüzey daha çok soğurur. Folyonun hangi tarafının dışta olduğu ısınma süresini etkiler."},{"q":"Sizce aşçı zamandan tasarruf sağlayabilmek için alüminyum folyonun hangi tarafını kullanmalıdır? Deney sonuçlarından elde ettiğiniz verileri kullanarak açıklayınız.","c":"Isı kaynağına mat taraf bakacak şekilde (parlak taraf yiyeceğe) sarmalıdır. Deneyde mat yüzey ısı ışınımını daha çok soğurduğu için aynı sıcaklığa daha kısa sürede ulaşıldı."},{"q":"Alüminyum folyonun parlak ya da mat tarafını kullanmak enerji tasarrufu açısından fark oluşturdu mu? Bunu deneydeki hangi verilerden anladınız?","c":"Evet, fark oluşturdu. Aynı sürede ölçülen sıcaklıklar ve hedef sıcaklığa ulaşma süreleri farklıydı. Daha kısa sürede ısınan düzenek daha az enerji harcar."},{"q":"Alüminyum folyonun parlak ve mat tarafları arasında ısı iletkenliği farkı var mıdır?","c":"Hayır. İki taraf da aynı metaldir, iletkenlikleri aynıdır. Fark, yüzeyin ışınımı yansıtma ve soğurma yeteneğinden kaynaklanır. Gerçek mutfak koşullarında bu fark küçüktür."},{"q":"Deneyde alüminyum folyo yerine kullanılabilecek farklı ürünler öneriniz.","c":"Pişirme kâğıdı (yağlı kâğıt), cam ya da seramik fırın kapları, paslanmaz çelik kaplar, silikon pişirme örtüleri."}],"ek":[{"q":"Bu deneyde bağımsız değişken hangisidir?","s":["Suyun sıcaklığı","Folyonun dışa bakan yüzeyi (parlak/mat)","Isıtıcının gücü","Su miktarı"],"d":1,"a":"Bilerek değiştirdiğimiz tek şey folyonun hangi tarafının dışa baktığıdır. Sıcaklık bağımlı değişkendir; ısıtıcı ve su miktarı kontrol değişkenleridir."},{"q":"Isıtıcı ve su miktarı neden iki düzenekte de aynı tutulur?","s":["Deney daha kısa sürsün diye","Farkın yalnızca folyo yüzeyinden kaynaklandığından emin olmak için","Termometre doğru ölçsün diye","Folyo yırtılmasın diye"],"d":1,"a":"Bunlar kontrol değişkenleridir. Sabit tutulmazsa sıcaklık farkının nedenini ayırt edemeyiz."}]},"buharbasinci":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 170–171 · Değerlendirme","kitap":[{"q":"Düşündüğünüz faktörler sıvının denge buhar basıncını etkiledi mi? Eğer etkilediyse bu durumun nedeni ne olabilir?","c":"Sıvının cinsi ve sıcaklık denge buhar basıncını etkiler; sıvı miktarı ve kabın hacmi etkilemez. Moleküller arası etkileşimi zayıf olan sıvıda tanecikler kolay buharlaşır, buhar basıncı yüksektir. Sıcaklık artınca daha çok tanecik buharlaşacak enerjiye ulaşır, buhar basıncı artar."},{"q":"Deneyi diğer sıvılarla tekrarlayarak üç sıvı için bulduğunuz sonuçları karşılaştırınız.","c":"Aynı sıcaklıkta denge buhar basıncı aseton > etil alkol > su sırasındadır. Aseton molekülleri arasında hidrojen bağı yoktur. Etanolde hidrojen bağı vardır ama sudakinden azdır. Su en güçlü etkileşime sahip olduğu için en düşük buhar basıncını gösterir."},{"q":"Sınıfta farklı araştırma sorularına yanıt bulmak için deney yapan arkadaşlarınızın deney sonuçlarını inceleyiniz. Sizce bir sıvının denge buhar basıncını etkileyen faktörler nelerdir?","c":"Sıvının cinsi (moleküller arası etkileşim kuvveti) ve sıcaklık. Sıvının miktarı, kabın şekli ve hacmi denge buhar basıncını değiştirmez."}],"ek":[{"q":"Kapalı kapta denge buhar basıncına ulaşıldığında hangisi doğrudur?","s":["Buharlaşma durur","Buharlaşma hızı yoğuşma hızına eşittir","Yoğuşma durur","Sıvının tamamı buharlaşır"],"d":1,"a":"Denge dinamiktir. Buharlaşma ve yoğuşma devam eder ama hızları eşittir, bu yüzden basınç sabit kalır."},{"q":"Aynı sıcaklıkta erlenmayere iki kat fazla aseton konulursa denge buhar basıncı ne olur?","s":["İki katına çıkar","Yarıya iner","Değişmez","Sıfır olur"],"d":2,"a":"Denge buhar basıncı yalnızca sıvının cinsine ve sıcaklığa bağlıdır, miktarına bağlı değildir."},{"q":"Kolonya cildimizde suya göre daha çabuk buharlaşır. Bunun nedeni hangisidir?","s":["Alkolün kaynama noktası daha yüksektir","Alkolün moleküller arası etkileşimi daha zayıf, buhar basıncı daha yüksektir","Alkol daha yoğundur","Su apolardır"],"d":1,"a":"Etkileşimi zayıf olan sıvının tanecikleri yüzeyden daha kolay kopar, buhar basıncı yüksektir ve hızlı buharlaşır."}]},"kaynama":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 175–176 · Değerlendirme","kitap":[{"q":"Şırınganın ucu kapalıyken pistonunun çekilmesi durumunda neler olabileceğini tahmin ediniz. Tahminlerinizi nedenleriyle açıklayınız.","c":"Piston çekilince suyun üzerindeki hacim artar ve basınç düşer. Basınç suyun buhar basıncının altına inerse 100 °C’ın altında olmasına rağmen su kaynamaya başlar."},{"q":"Deneyde gerçekleşen olayları gözlemleyiniz ve gözlemlerinizi yazınız.","c":"Piston çekildiğinde ılık suyun (yaklaşık 50 °C) içinde kabarcıklar oluştu ve su kaynadı. Piston bırakılınca kabarcıklar kayboldu."},{"q":"Şırınganın pistonu çekilerek hacim değiştirildiğinde basınçta nasıl bir değişim olduğunu düşünüyorsunuz? Bu durumun nedenini açıklayınız.","c":"Basınç azalır. Aynı miktar gaz daha büyük hacme yayıldığı için taneciklerin birim alana çarpma sayısı azalır."},{"q":"Gözlemlediğiniz olayı topladığınız verilere dayanarak nedenleriyle açıklayınız ve deneyin amacı bölümünü doldurunuz.","c":"Sıvı, buhar basıncı dış basınca eşit olduğunda kaynar. Dış basınç düşürülünce suyun 50 °C’taki buhar basıncı dış basınca eşit oldu ve su kaynadı. Deneyin amacı: dış basıncın kaynama sıcaklığına etkisini gözlemleyebilme."},{"q":"Tahminleriniz ile gözlemleriniz arasında karşılaştırmalar yapınız. Tahminleriniz gerçekleşti mi? Tahminleriniz ve gözlemleriniz arasında tutarsızlık varsa bunun nedenlerine ilişkin yorumlarda bulununuz ve sınıf arkadaşlarınızla saygı çerçevesinde tartışınız.","c":"Kişisel cevap. Pek çok öğrenci suyun yalnızca 100 °C’ta kaynayacağını düşünür. Gözlem, kaynama sıcaklığının dış basınca bağlı olduğunu gösterir."}],"ek":[{"q":"Yüksek bir dağın tepesinde su kaç °C’ta kaynar?","s":["100 °C’ın üstünde","Tam 100 °C’ta","100 °C’ın altında","Hiç kaynamaz"],"d":2,"a":"Yükseklerde açık hava basıncı düşüktür. Suyun buhar basıncı bu düşük basınca daha düşük sıcaklıkta eşitlenir."},{"q":"Düdüklü tencerede yemeklerin daha çabuk pişmesinin nedeni nedir?","s":["İçerideki basınç arttığı için suyun kaynama sıcaklığı yükselir","Su daha az buharlaşır, sıcaklık düşer","Tencerenin metali daha iyi iletir","Kapak ışığı yansıtır"],"d":0,"a":"Kapalı tencerede basınç 1 atm’nin üstüne çıkar. Su 100 °C’ın üzerinde kaynar, yemek daha yüksek sıcaklıkta pişer."}]},"kaynama2":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 177–178 · Değerlendirme","kitap":[{"q":"Sıvıların tanecikleri arasındaki etkileşimleri inceleyerek etkileşim türlerini belirleyiniz.","c":"Su: hidrojen bağı (+ dipol-dipol, London). Etanol: hidrojen bağı (+ dipol-dipol, London). Aseton: dipol-dipol ve London kuvvetleri; aseton molekülleri arasında hidrojen bağı yoktur."},{"q":"Sıvıların etkileşim kuvvetlerini kıyaslayınız.","c":"Su > etanol > aseton. Su molekülü iki H ve iki ortaklanmamış elektron çifti ile daha çok hidrojen bağı kurar. Etanolde hidrojen bağı kuran tek –OH grubu vardır. Asetonda hidrojen bağı yoktur."},{"q":"Sıvıların etkileşim kuvvetleri ve belirlediğiniz kaynama sıcaklıkları arasında nasıl bir ilişki vardır? Açıklayınız.","c":"Doğru orantılı bir ilişki vardır. Etkileşim kuvveti arttıkça tanecikleri birbirinden ayırmak için daha çok enerji gerekir ve kaynama sıcaklığı yükselir: su 100 °C > etanol 78 °C > aseton 56 °C."},{"q":"Tahminleriniz ve gözlemleriniz arasında karşılaştırmalar yapınız. Tahminlerinizle gözlemleriniz arasında tutarsızlık var mı? Eğer tahminlerinizle gözlemleriniz arasında tutarsızlık varsa bunun nedenlerini açıklayınız.","c":"Kişisel cevap. Tutarsızlık varsa nedeni çoğunlukla etkileşim türlerinin karıştırılmasıdır (örneğin asetonda hidrojen bağı olduğunu sanmak) ya da ölçümde termometrenin yanlış yerleştirilmesidir."}],"ek":[{"q":"Kaynama süresince saf sıvının sıcaklığı için hangisi doğrudur?","s":["Sürekli artar","Sabit kalır","Önce azalır sonra artar","Sürekli azalır"],"d":1,"a":"Verilen ısı tanecikleri birbirinden ayırmaya harcanır. Saf sıvı kaynarken sıcaklık sabit kalır."},{"q":"Etanol ve aseton ısıtılırken neden açık alevle değil su banyosu ya da ısıtıcı ile ısıtılır?","s":["Daha hızlı ısınsın diye","Bu sıvılar kolay alev alır, açık alev yangın riski taşır","Su banyosu daha ucuzdur","Aseton suyla tepkimeye girer"],"d":1,"a":"Etanol ve aseton uçucu ve yanıcıdır. Buharları açık alevle tutuşabilir; laboratuvar güvenliği için kapalı ısıtıcı kullanılır."}]},"akiskanlik":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 190–191 · Değerlendirme","kitap":[{"q":"Deneyde kullandığınız sıvıların akışkanlıkları ile moleküller arası etkileşim kuvvetleri arasındaki örüntüyü belirleyerek aşağıya yazınız.","c":"Moleküller arası etkileşim kuvveti arttıkça bilyenin düşme süresi uzadı, yani akışkanlık azaldı: aseton > etil alkol > gliserin. Bilye asetonda en hızlı, gliserinde en yavaş düştü."},{"q":"Deneyden elde ettiğiniz örüntüleri kullanarak sıvıların akışkanlığını sıvının moleküller arası etkileşim kuvveti ile ilişkilendirerek açıklayınız.","c":"Güçlü etkileşimler moleküllerin birbirinin üzerinden kaymasını zorlaştırır. Bu yüzden etkileşimi güçlü sıvının akışkanlığı az, viskozitesi yüksektir. Gliserin molekülünde üç –OH grubu olduğu için çok sayıda hidrojen bağı kurar ve en viskoz sıvıdır."},{"q":"Aşağıda benzen ve su moleküllerinin yapısı verilmiştir. Benzen ve suyun vizkozite değerleri ise Tablo 2.6’da verilmiştir. Benzenin viskozitesinin suya göre daha düşük, akışkanlığının daha yüksek olmasının nedenini moleküller arası etkileşimleri kullanarak açıklayınız.","c":"Benzen apolardır, molekülleri arasında yalnızca London kuvvetleri vardır. Su molekülleri arasında güçlü hidrojen bağları bulunur. Benzende etkileşim daha zayıf olduğu için moleküller kolay kayar; viskozitesi düşük, akışkanlığı yüksektir."}],"ek":[{"q":"Bu deneyde akışkanlık neyle ölçüldü?","s":["Sıvının rengiyle","Bilyenin sıvı içinde belirli bir yolu düşme süresiyle","Sıvının kütlesiyle","Tüpün çapıyla"],"d":1,"a":"Düşme süresi uzadıkça sıvının akmaya karşı direnci (viskozitesi) büyüktür, akışkanlığı azdır."},{"q":"Deneyde bilyelerin aynı ve sıvı sıcaklıklarının eşit olmasının nedeni nedir?","s":["Kontrol değişkenleridir; fark yalnızca sıvının cinsinden kaynaklanmalı","Bilyeler daha hızlı düşsün diye","Sıvılar karışmasın diye","Tüpler kırılmasın diye"],"d":0,"a":"Bilye boyutu ve sıcaklık da düşme süresini değiştirir. Sabit tutulmazsa sıvı cinsinin etkisini ayırt edemeyiz."}]},"akiskanlik2":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 193 · Değerlendirme","kitap":[{"q":"Seçtiğiniz sıvıların akışkanlığı ile sıcaklıkları arasındaki örüntüyü belirleyerek aşağıya yazınız.","c":"Sıcaklık arttıkça bilyenin düşme süresi kısaldı. Her sıvıda sıcaklık arttıkça akışkanlık arttı, viskozite azaldı."},{"q":"Deneyden elde ettiğiniz örüntüleri kullanarak sıvıların akışkanlığı ile sıcaklık arasındaki ilişkiyi açıklayınız.","c":"Sıcaklık artınca moleküllerin kinetik enerjisi artar ve moleküller arası etkileşimler daha kolay yenilir. Moleküller birbirinin üzerinden kolay kayar; akışkanlık artar, viskozite azalır."},{"q":"Zeytinyağının viskozitesinin (81.10⁻³ Pa.s) suyun (1,01.10⁻³ Pa.s) viskozitesine eşit hâle nasıl getirilebileceğini açıklayınız.","c":"Zeytinyağı ısıtılmalıdır. Sıcaklık arttıkça viskozitesi azalır; yeterince yüksek bir sıcaklıkta suyun oda sıcaklığındaki viskozitesine yaklaşır. Su soğutulursa da viskozitesi biraz artar."}],"ek":[{"q":"Reçelin kavanozlara sıcakken doldurulmasının nedeni hangisidir?","s":["Sıcakken viskozitesi düşük olduğu için kolay akar","Sıcakken daha tatlıdır","Soğuyunca buharlaşır","Sıcak reçel daha yoğundur"],"d":0,"a":"Sıcaklık arttıkça viskozite azalır; reçel ısıtılınca daha kolay akar ve doldurulur."},{"q":"Bu deneyde bağımlı değişken hangisidir?","s":["Sıcaklık","Sıvının cinsi","Bilyenin düşme süresi","Bilyenin boyutu"],"d":2,"a":"Değiştirdiğimiz sıcaklığa bağlı olarak ölçtüğümüz büyüklük bilyenin düşme süresidir."}]},"damla":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 201 · Değerlendirme","kitap":[{"q":"Damlaların boyut ve şekillerinin farklı olmasının nedeni ne olabilir? Bu farklılığı moleküller arası etkileşimlerle ilişkilendirerek açıklayınız.","c":"Damla, kohezyon kuvvetleri yer çekimine dayanabildiği sürece büyür. Molekülleri arasında güçlü etkileşim (hidrojen bağı) olan su daha büyük damla oluşturur. Etkileşimi zayıf olan zeytinyağı ise küçük damlalar hâlinde düşer."},{"q":"Damlaların boyutlarından yola çıkarak bu sıvıların yüzey gerilimlerini karşılaştırınız.","c":"Damla büyüdükçe (aynı hacim için damla sayısı azaldıkça) yüzey gerilimi büyüktür. Deneydeki damla sayıları su 20, şurup 26, gliserin 29, zeytinyağı 41’dir. Buna göre yüzey gerilimi su > şurup > gliserin > zeytinyağı sırasındadır."},{"q":"Bu sıvıların literatürdeki yüzey gerilim değerlerini “edu.tr” ve “gov.tr” uzantılı genel ağ kaynaklarını kullanarak bulunuz. Bulduğunuz yüzey gerilim değerlerini tahminlerinizle karşılaştırınız.","c":"20 °C’ta yaklaşık değerler: su 0,073 N/m, gliserin 0,063 N/m, zeytinyağı 0,032 N/m. Şuruptaki şeker de suyun yüzey gerilimini çok az değiştirir. Sıralama deneydeki damla büyüklükleriyle uyumludur."}],"ek":[{"q":"Büretten aynı hacimde sıvı akıtıldığında damla sayısı fazla olan sıvı için ne söylenebilir?","s":["Yüzey gerilimi büyüktür","Yüzey gerilimi küçüktür","Yoğunluğu sıfırdır","Kaynama noktası yüksektir"],"d":1,"a":"Yüzey gerilimi küçük sıvının damlası erken kopar, küçük olur. Aynı hacim daha çok damlaya bölünür."},{"q":"Su örümceklerinin su yüzeyinde batmadan yürüyebilmesi hangi özellikle ilgilidir?","s":["Viskozite","Yüzey gerilimi","Buhar basıncı","Kaynama noktası"],"d":1,"a":"Yüzeydeki su molekülleri içe doğru çekilir ve gergin bir zar gibi davranır. Hafif canlılar bu “zar” üzerinde durabilir."}]},"yuzeygerilim":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 206–208 · Değerlendirme (üç deney)","kitap":[{"q":"Bağımsız değişkeninizi değiştirdiğinizde damlalarının biçim ve boyutları arasında nasıl bir fark oluştu? Bu farkın oluşmasının sebebi ne olabilir?","c":"Sıvı cinsi değişince damlaların büyüklüğü değişti. Suyun damlaları en büyük oldu, etil alkolün damlaları çok küçük kaldı (1 mL’deki damla sayısı arttı). Sebebi moleküller arası çekim (kohezyon) kuvvetlerinin farklı olmasıdır."},{"q":"Deneyde kullandığınız sıvıların sahip olduğu moleküller arası çekim kuvveti ile damla sayısı arasında nasıl bir ilişki olduğunu açıklayınız.","c":"Çekim kuvveti arttıkça damlalar büyüdü, 1 mL’deki damla sayısı azaldı. Güçlü kohezyon damlanın uçta daha uzun süre tutunmasını sağlar. (Kitaptaki bozuk para yönteminde ise tam tersine paraya sığan damla sayısı artar.)"},{"q":"Ortalama damla sayılarından yararlanarak sıvıların yüzey gerilimlerini karşılaştırınız.","c":"1 mL’deki damla sayısı azaldıkça yüzey gerilimi büyüktür. Deneydeki sıra su > gliserin > etil alkoldür; bu sıra literatür değerleriyle (0,073 – 0,063 – 0,022 N/m) uyumludur."},{"q":"Bağımsız değişkeni değiştirdiğinizde paranın yüzeyinde oluşan şekiller arasında nasıl bir fark oluştu? Bu farkın oluşmasının sebebi ne olabilir? (Sıcaklık ve çözünen madde deneyleri)","c":"Su ısıtılınca ya da suya deterjan eklenince damlalar küçüldü (paranın üzerindeki kubbe de basıklaşır ve erken taşar). Sıcaklık moleküllerin kinetik enerjisini artırarak, deterjan ise yüzeye yerleşerek su molekülleri arasındaki çekimi zayıflatır. Tuz eklemek ise yüzey gerilimini çok az artırır."},{"q":"Bağımsız değişkeni değiştirmeniz damla sayısında nasıl bir fark yarattı? Bu farkın sebebini moleküller arası etkileşimler temelinde açıklayınız.","c":"Sıcak suda ve deterjanlı suda büretten akan 1 mL’deki damla sayısı arttı, yani damlalar küçüldü (para üzerinde ise sığan damla sayısı azalır). Sıcaklık artışı hidrojen bağlarının etkisini zayıflatır. Sabun molekülleri yüzeyde su molekülleri arasına girerek kohezyonu azaltır. Sonuçta yüzey gerilimi düşer."}],"ek":[{"q":"Suya deterjan eklenmesi yüzey gerilimini nasıl etkiler?","s":["Artırır","Azaltır","Değiştirmez","Önce artırır sonra azaltır"],"d":1,"a":"Deterjan (yüzey aktif madde) molekülleri yüzeye yerleşir ve su molekülleri arasındaki çekimi zayıflatır."},{"q":"Bulaşıkların sıcak suyla daha kolay yıkanmasının bir nedeni nedir?","s":["Sıcak suyun yüzey gerilimi daha düşüktür, yüzeyleri daha iyi ıslatır","Sıcak su daha yoğundur","Sıcak suyun yüzey gerilimi daha yüksektir","Sıcak su yağla tepkimeye girer"],"d":0,"a":"Sıcaklık arttıkça yüzey gerilimi azalır; su yüzeylere daha kolay yayılır ve kiri daha iyi ıslatır."},{"q":"Bu deneylerde paranın büyüklüğü ve damlalığın aynı tutulmasının nedeni nedir?","s":["Kontrol değişkenleridir","Bağımlı değişkendir","Bağımsız değişkendir","Deneyi hızlandırır"],"d":0,"a":"Damla boyutunu ve paranın alabileceği sıvı miktarını etkilediklerinden sabit tutulmaları gerekir."}]},"nano":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 245 · Değerlendirme","kitap":[{"q":"Gümüş nanoparçacık içeren çözeltiyi inceleyiniz. Bu çözeltinin gümüş metalinden farkları nelerdir?","c":"Gümüş metali parlak, gri-beyaz bir katıdır. Nanoparçacık içeren çözelti ise sarı-kahverengi, saydam görünümlü bir karışımdır. Parçacıklar çok küçük olduğu için ışığı farklı soğurur ve sıvı içinde dağılmış hâlde kalır."},{"q":"Gümüş nanoparçacık içeren çözeltiyi süzünüz. Çözeltiyi süzdüğünüzde nanoparçacıkları çözeltiden ayırabildiniz mi?","c":"Hayır. Nanoparçacıklar (1–100 nm) süzgeç kâğıdının gözeneklerinden çok küçüktür, süzgeçten geçerler."},{"q":"Bakır tozunu ve bakır nanoparçacık içeren çözeltiyi inceleyerek bunların arasındaki farkları açıklayınız.","c":"Bakır tozu kırmızımsı, gözle görülen katı tanecikler hâlindedir ve suda dibe çöker. Bakır nanoparçacık çözeltisi ise koyu renkli, dağılmış bir karışımdır; parçacıklar gözle görülmez ve kolay çökmez."},{"q":"Sizce gümüş nanoparçacığın Ag atomundan ve Ag⁺ iyonundan farkı nedir?","c":"Ag atomu tek bir atomdur. Ag⁺ iyonu bir elektron vermiş, yüklü bir taneciktir (AgNO₃ çözeltisinde bulunur). Gümüş nanoparçacık ise binlerce yüksüz gümüş atomunun bir araya geldiği 1–100 nm boyutunda bir kümedir."},{"q":"Sizce bakır nanoparçacığın Cu atomundan ve Cu²⁺ iyonundan farkı nedir?","c":"Cu atomu tek atom, Cu²⁺ iki elektron vermiş mavi renkli iyondur. Bakır nanoparçacık, Cu²⁺ iyonlarının indirgenmesiyle oluşan çok sayıda bakır atomundan meydana gelen nano boyutlu kümedir."},{"q":"Deneyde oluşturduğunuz gümüş nanoparçacıklarının küresel yapıda ve yaklaşık 5 nm çapında olduğu düşünülürse bir gümüş nanoparçacığın kaç adet Ag atomu içerdiğini hesaplayınız. (1 Ag atomu yarıçapı rAg = 144 pm, 1 nm = 1000 pm)","c":"Nanoparçacık yarıçapı 2,5 nm = 2500 pm. Atom sayısı ≈ (R/r)³ = (2500/144)³ ≈ 17,4³ ≈ 5 200 atom. (Atomlar arasındaki boşluklar hesaba katılırsa yaklaşık 3 800 atom bulunur.)"},{"q":"Hazırladığınız çözeltiler gümüş nanoparçacık (AgNP) ve bakır nanoparçacık (CuNP) içermektedir. Sizce nanoparçacık nedir?","c":"Çapı 1–100 nm arasında olan atomik ya da moleküler parçacıklardır. Yüzey alanı/hacim oranları çok büyük olduğu için aynı maddenin büyük parçalarından farklı özellikler gösterirler."}],"ek":[{"q":"Bir maddenin parçacık boyutu küçüldükçe yüzey alanı/hacim oranı nasıl değişir?","s":["Azalır","Artar","Değişmez","Sıfır olur"],"d":1,"a":"Parçacık küçüldükçe atomların daha büyük bir kısmı yüzeyde bulunur; yüzey alanı/hacim oranı artar."},{"q":"AgNP eldesinde AgNO₃ çözeltisindeki Ag⁺ iyonlarına ne olur?","s":["Yükseltgenir","İndirgenerek Ag atomlarına dönüşür","Buharlaşır","Değişmeden kalır"],"d":1,"a":"İndirgen madde (örneğin sodyum sitrat) Ag⁺ iyonlarına elektron verir; oluşan Ag atomları nano boyutlu kümeler hâlinde toplanır."}]},"nano2":{"kaynak":"MEB 9. sınıf Kimya ders kitabı, s. 250 · Değerlendirme","kitap":[{"q":"Deney sonuçlarınızı öğretmeninizin deney sonuçlarıyla karşılaştırınız. Gümüş ve bakır nanoparçacık elde ettiğinizi nasıl belirlediniz?","c":"Renk değişiminden: AgNO₃ çözeltisi özüt eklenince sarı-kahverengiye, Cu²⁺ çözeltisi ise kahverengi-siyaha döndü. Çözeltinin süzgeçten geçmesi ve ışık demetini saçması da nanoparçacık oluştuğunu gösterir."},{"q":"Elde ettiğiniz bakır nanoparçacık miktarını belirleyiniz. Hangi atıktan daha fazla bakır nanoparçacık elde ettiniz? Sizce bunun nedeni ne olabilir?","c":"Laboratuvarda en çok kütle veren atık hangisiyse o yazılır. Fark, atığın özütündeki indirgen madde (polifenol, C vitamini vb.) miktarından kaynaklanır: indirgen madde ne kadar çoksa o kadar çok Cu²⁺ indirgenir."},{"q":"Elde ettiğiniz gümüş nanoparçacıkların verimini bakır nanoparçacık deneyinizdeki kadar kolay belirleyebildiniz mi? Bu durumun nedeni nedir?","c":"Hayır. Gümüş nanoparçacıklar çok küçük ve dağılmış hâlde kaldığı için çöktürülüp tartılmaları zordur. Ayrıca kullanılan AgNO₃ miktarı az olduğundan oluşan kütle de çok küçüktür."},{"q":"1 ila 100 nm büyüklüğündeki parçacıklara nanoparçacık adı verilir. Atıklardan elde ettiğiniz nanoparçacıkların büyüklüğünü ve şeklini nasıl belirleyebilirsiniz?","c":"Normal mikroskopla göremeyiz. Elektron mikroskobu (TEM, SEM), dinamik ışık saçılması (DLS) ve UV-görünür bölge spektroskopisi gibi yöntemler kullanılır."},{"q":"Atıklardan gümüş ve bakır nanoparçacık eldesinde yeşil kimyanın hangi ilkelerini kullandığınızı açıklayınız. Bu ilkeler sürdürülebilir kalkınmanın hangi hedeflerine ulaşmanızı sağlamış olabilir?","c":"Atık önleme, yenilenebilir hammadde kullanma ve daha az zararlı kimyasal kullanma ilkeleri. Sentetik indirgenler yerine meyve-sebze kabuklarından elde edilen özüt kullanıldı. Bu, sürdürülebilir kalkınmanın 12. hedefine (sorumlu üretim ve tüketim) katkı sağlar."}],"ek":[{"q":"Bu deneyde meyve-sebze kabuğu özütü hangi görevi üstlenir?","s":["Çözücü","İndirgen madde","Katalizör","İndikatör"],"d":1,"a":"Özütteki polifenoller ve vitaminler metal iyonlarına elektron vererek onları metal atomlarına indirger."},{"q":"Yeşil kimyanın “atık önleme” ilkesi neyi savunur?","s":["Oluşan atığı arıtmayı","Atığı oluşmadan önlemeyi","Atığı denize boşaltmayı","Atığı yakmayı"],"d":1,"a":"Atığı oluştuktan sonra arıtmak yerine hiç oluşmamasını sağlamak daha iyidir; evsel atığı hammadde olarak kullanmak bu ilkeye örnektir."}]},"degisim":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 24–25 · Bulgular ve Sonuç, Değerlendirme","kitap":[{"q":"Kimyasal değişimlerde gözlemlenemez değişimler var mıdır?","c":"Evet. Bazı tepkimelerde renk, gaz, çökelek ya da sıcaklık değişimi gözle fark edilmeyecek kadar azdır. Asit ile bazın tepkimesi gibi olaylarda değişim ancak pH ölçümü, iletkenlik ya da indikatörle anlaşılır."},{"q":"Kimyasal değişimlerde tanecikler arasında nasıl bir etkileşim olabilir?","c":"Tepkimeye giren taneciklerdeki bağlar kopar, atomlar yeniden düzenlenir ve yeni bağlar oluşur. Atomların cinsi ve sayısı korunur, ancak farklı özellikte yeni maddeler meydana gelir."},{"q":"Kimyasal değişimin gözlemlediğiniz değişkenler dışında farklı kanıtları olabilir mi? Günlük hayattan örnekler vererek açıklayınız.","c":"Evet: koku değişimi (sütün ekşimesi, yumurtanın bozulması), ışık oluşumu (mum ve odunun yanması, havai fişek), iletkenlik ya da pH değişimi, tat değişimi (meyvenin olgunlaşması)."},{"q":"Bir gözlemci, iki maddeyi birbiri içinde karıştırarak elde ettiği karışımda meydana gelen değişimin fiziksel değişim olduğunu ya da maddelerin kimyasal tepkimeye mi girdiğini nasıl belirleyebilir? Örneklerle açıklayınız.","c":"Yeni bir maddenin oluştuğunu gösteren kanıtlara bakar: gaz çıkışı (sirke + soda), çökelek oluşumu (KI + Pb(NO₃)₂ ile sarı PbI₂), renk değişimi, sıcaklık değişimi. Şekerin suda çözünmesi gibi olaylarda yeni madde oluşmaz ve madde geri kazanılabilir; bu fiziksel değişimdir."},{"q":"Kimyasal değişimi tanecik boyutunda incelediğinizde maddelerin iç yapılarındaki değişimle ilgili neler söyleyebilirsiniz? Arkadaşlarınızla tartışınız.","c":"Kimyasal değişimde maddenin tanecik yapısı değişir: molekül ya da iyonlar arasındaki bağlar kopar, aynı atomlar farklı biçimde bağlanır. Örneğin H₂O₂ molekülleri H₂O ve O₂ moleküllerine dönüşür. Fiziksel değişimde ise tanecikler aynı kalır, yalnızca aralarındaki uzaklık ve düzen değişir."}],"ek":[{"q":"Sirke ile yemek sodası tepkimesinde balonun şişmesi hangi kimyasal değişim göstergesidir?","s":["Renk değişimi","Gaz çıkışı","Çökelek oluşumu","Işık oluşumu"],"d":1,"a":"Tepkimede CO₂ gazı oluşur ve balonu şişirir."},{"q":"Fil diş macunu deneyinde KI’nin görevi nedir?","s":["Tepkimeye girip tükenir","H₂O₂’nin ayrışmasını hızlandıran katalizördür","Köpüğü renklendirir","Ortamı soğutur"],"d":1,"a":"KI, H₂O₂’nin su ve oksijene ayrışmasını hızlandırır ve tepkime sonunda değişmeden kalır."},{"q":"Pb(NO₃)₂ ve KI çözeltileri karıştırıldığında oluşan sarı katı hangisidir?","s":["KNO₃","PbI₂","KI","Pb"],"d":1,"a":"Pb²⁺ ve I⁻ iyonları birleşerek suda çok az çözünen sarı PbI₂ çökeleğini oluşturur; KNO₃ çözeltide kalır."}]},"cokelme":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 39 · Değerlendirme (1. soru, I. istasyon)","kitap":[{"q":"I. istasyonda yapmış olduğunuz deneyde farklı iki çözelti karıştırıldığında bir çökelme meydana gelmiştir. Bunun nedeni sizce ne olabilir?","c":"AgNO₃ çözeltisindeki Ag⁺ iyonları ile NaCl çözeltisindeki Cl⁻ iyonları birleşerek suda çok az çözünen AgCl katısını oluşturur. Bu katı çözeltiden ayrılıp beyaz bir çökelek olarak dibe çöker. Na⁺ ve NO₃⁻ iyonları ise çözeltide kalır."}],"ek":[{"q":"AgNO₃(suda) + NaCl(suda) tepkimesinde seyirci iyonlar hangileridir?","s":["Ag⁺ ve Cl⁻","Na⁺ ve NO₃⁻","Ag⁺ ve Na⁺","Cl⁻ ve NO₃⁻"],"d":1,"a":"Na⁺ ve NO₃⁻ tepkimeden önce de sonra da çözeltide serbest hâlde bulunur; tepkimeye katılmazlar."},{"q":"Bu tepkimenin net iyon denklemi hangisidir?","s":["Na⁺ + Cl⁻ → NaCl(k)","Ag⁺(suda) + Cl⁻(suda) → AgCl(k)","Ag(k) + Cl₂(g) → AgCl(k)","AgNO₃ → Ag⁺ + NO₃⁻"],"d":1,"a":"Net iyon denklemi yalnızca tepkimeye giren iyonları ve oluşan katıyı gösterir."},{"q":"Çaydanlıkta kireç birikmesi hangi tepkime türüne örnektir?","s":["Yanma","Çökelme","Nötralleşme","Redoks"],"d":1,"a":"Sudaki Ca²⁺ ve CO₃²⁻ iyonları ısınınca suda az çözünen CaCO₃ katısı hâlinde çöker."}]},"redoks":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 39 · Değerlendirme (2. soru, II. istasyon)","kitap":[{"q":"II. istasyonda yaptığınız deneyi göz önünde bulundurarak alüminyum tencerelerde yemek yapmanın ve muhafaza etmenin insan sağlığına etkileri hakkındaki düşüncelerinizi yazınız.","c":"Deneyde alüminyum asitle tepkimeye girerek Al³⁺ iyonu hâline geçti ve H₂ gazı çıktı. Benzer şekilde domates, limon, sirke gibi asidik yiyecekler alüminyum tencerede pişirilir ya da bekletilirse alüminyum yemeğe geçebilir. Uzun süreli alüminyum alımı sağlık riski taşıyabileceğinden asidik yiyecekler alüminyum kaplarda pişirilmemeli ve saklanmamalıdır."}],"ek":[{"q":"2Al + 6HCl → 2AlCl₃ + 3H₂ tepkimesinde yükseltgenen tür hangisidir?","s":["H⁺","Cl⁻","Al","H₂"],"d":2,"a":"Al atomları elektron vererek Al³⁺ iyonuna dönüşür; elektron veren tür yükseltgenir."},{"q":"Aynı tepkimede indirgenen tür hangisidir?","s":["Al","H⁺","Cl⁻","AlCl₃"],"d":1,"a":"H⁺ iyonları elektron alarak H₂ gazına dönüşür; elektron alan tür indirgenir."},{"q":"Tepkimede çıkan gazın H₂ olduğu nasıl anlaşılır?","s":["Kireç suyunu bulandırır","Yanan kibrit yaklaştırıldığında “pıt” sesiyle yanar","Turnusolü kırmızıya çevirir","Kokusu vardır"],"d":1,"a":"Hidrojen gazı yanıcıdır; ağzına yanan kibrit tutulan tüpte küçük bir patlama sesi duyulur."}]},"asitbaz":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 39 · Değerlendirme (3. ve 4. soru, III. istasyon)","kitap":[{"q":"III. istasyondaki çözeltilerin pH değerleri nasıl değişti? Bunun nedeni sizce ne olabilir?","c":"HCl çözeltisinin pH değeri başta çok düşüktü. KOH eklendikçe pH yükseldi, eşdeğerlik noktasında 7 oldu (fenolftalein pembeleşmeye başladı), fazla baz eklenince 7’nin üstüne çıktı. Nedeni: asitten gelen H⁺ iyonları bazdan gelen OH⁻ iyonlarıyla birleşip su oluşturur ve H⁺ derişimi azalır."},{"q":"Asit-baz tepkimesinde oluşan tuz, çözelti içinde katı olarak gözlemlenmekte midir? Nedenini tartışınız.","c":"Hayır. Oluşan KCl suda iyi çözünen bir tuzdur; K⁺ ve Cl⁻ iyonları çözeltide serbest hâlde kalır. Tuzu katı olarak görmek için suyun buharlaştırılması gerekir."}],"ek":[{"q":"HCl + KOH → KCl + H₂O tepkimesinin net iyon denklemi hangisidir?","s":["K⁺ + Cl⁻ → KCl","H⁺ + OH⁻ → H₂O","HCl → H⁺ + Cl⁻","KOH → K⁺ + OH⁻"],"d":1,"a":"Kuvvetli asit ile kuvvetli bazın tepkimesinde aslında gerçekleşen olay H⁺ ve OH⁻ iyonlarının su oluşturmasıdır."},{"q":"Fenolftalein bazik ortamda hangi rengi alır?","s":["Renksiz","Pembe","Sarı","Mavi"],"d":1,"a":"Fenolftalein asidik ve nötr ortamda renksiz, pH ≈ 8,2’nin üstünde pembedir."}]},"olcek":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 236–237 · Bulgular ve Sonuç, Değerlendirme","kitap":[{"q":"Makro ve mikro ölçekli deneylerin sonuçlarını incelediğinizde herhangi bir farklılık gözlemlediniz mi? Gözlemlediğiniz farklılıklar var ise yazınız.","c":"Tepkimenin türü ve gözlemler (çökelek oluşumu, gaz çıkışı) aynıydı. Fark yalnızca miktardaydı: mikro ölçekte çok daha az kimyasal ve su kullanıldı, daha az atık oluştu ve deney daha kısa sürdü. Mikro ölçekte gözlem küçük olduğu için dikkatli bakmak gerekir."},{"q":"Bilimsel çalışmalarda yapılan deneylerde mikro ölçek kullanmanın avantaj ve dezavantajlarını yazınız.","c":"Avantajları: daha az kimyasal ve su harcanır, daha az atık oluşur, maliyet ve kaza riski azalır, deney kısa sürer. Dezavantajları: gözlem zorlaşabilir, küçük ölçüm hataları sonucu daha çok etkiler, hassas araç gerekebilir."},{"q":"Bilimsel çalışmalarda su ayak izi ve kimyasal kirliliği azaltmak için farklı neler yapılabilir? Düşüncelerinizi paylaşınız.","c":"Mikro ölçekli deneyler yapmak, kullanılmayan çözeltileri saklayıp yeniden kullanmak, çevreye zararsız kimyasalları tercih etmek, atıkları türüne göre ayırıp uygun şekilde bertaraf etmek, temizlikte az su kullanmak, sanal laboratuvarlardan yararlanmak."},{"q":"Deney sonunda elde ettiğiniz ürünleri çevreye zarar vermeden nasıl kaldırdınız? Açıklayınız.","c":"Gümüş içeren çökelek ve çözeltiler lavaboya dökülmeyip etiketli atık kabında toplanmalıdır. Asit ve baz atıkları nötrleştirildikten sonra bol suyla atılabilir. Kullanılmayan çözeltiler sonraki deneyler için saklanmalıdır."}],"ek":[{"q":"Atom ekonomisi yüksek bir tepkime için hangisi doğrudur?","s":["Tepkenlerdeki atomların çoğu istenen ürüne geçer","Çok fazla yan ürün oluşur","Tepkime çok yavaştır","Tepkimede su kullanılmaz"],"d":0,"a":"Atom ekonomisi, tepkenlerdeki atomların ne kadarının istenen üründe yer aldığını gösterir."},{"q":"Kuyu plakasında (mikro ölçek) yapılan çökelme deneyinde gözlenen çökelek makro ölçektekiyle aynı mıdır?","s":["Evet, aynı tepkime olduğu için aynı çökelek oluşur","Hayır, farklı bir madde oluşur","Mikro ölçekte çökelek oluşmaz","Mikro ölçekte gaz oluşur"],"d":0,"a":"Ölçek değişir, kimya değişmez. Daha az madde kullanılır ama aynı ürün oluşur."}]},"graham":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 104 · Değerlendirme","kitap":[{"q":"Tasarladığınız deney sonuçlarına göre gazların yayılma hızını etkileyen faktörleri belirleyiniz ve bu faktörlerin birbiriyle ilişkisini açıklayınız.","c":"Mol kütlesi ve sıcaklık. Aynı sıcaklıkta mol kütlesi küçük olan gaz daha hızlı yayılır (Graham yasası: v₁/v₂ = √(M₂/M₁)); NH₃ (17 g/mol) HCl’den (36,5 g/mol) hızlı olduğu için beyaz NH₄Cl halkası HCl tarafına yakın oluştu. Sıcaklık arttıkça tüm gazların ortalama hızı artar."}],"ek":[{"q":"80 cm’lik boruda NH₃ ve HCl aynı anda salınırsa beyaz halka NH₃ ucundan yaklaşık kaç cm uzakta oluşur?","s":["Yaklaşık 32 cm","Yaklaşık 40 cm","Yaklaşık 47 cm","Yaklaşık 60 cm"],"d":2,"a":"Hız oranı √(36,5/17) ≈ 1,47. NH₃ yolun 1,47/2,47 ≈ %59,4’ünü alır: 80 × 0,594 ≈ 47,5 cm."},{"q":"Odada açılan parfümün kokusunun yayılması hangi olaya örnektir?","s":["Efüzyon","Difüzyon","Yoğuşma","Süblimleşme"],"d":1,"a":"Gaz taneciklerinin başka bir gazın içinde yavaş yavaş karışarak yayılmasına difüzyon denir."},{"q":"Aynı sıcaklıkta He ve CH₄ gazlarından hangisi daha hızlı yayılır? (He: 4, CH₄: 16 g/mol)","s":["CH₄, 2 kat hızlı","He, 2 kat hızlı","He, 4 kat hızlı","Eşit hızda"],"d":1,"a":"v(He)/v(CH₄) = √(16/4) = 2."}]},"cozunurluk":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 170 · Bulgular ve Sonuç, Değerlendirme","kitap":[{"q":"Deney sonuçlarını kullanarak çözünürlüğe ilişkin bir tanım yapınız.","c":"Belirli bir sıcaklıkta 100 g suda çözünebilen en fazla madde miktarına çözünürlük denir. Deneyde bu sınır aşılınca eklenen katı çözünmeden dipte kaldı."},{"q":"Aşağıdaki tabloda maddelerin 100 g sudaki çözünürlükleri verilmiştir. (Sakkaroz: 20 °C’ta 201,9 g, 60 °C’ta 288,9 g; NaCl: 20 °C’ta 35,7 g, 60 °C’ta 37,1 g) 60 °C sıcaklıkta 288,9 g sakkaroz ve 37,1 g sodyum klorürün 100 g su içerisinde çözünmesiyle iki ayrı çözelti hazırlanıyor. Her iki çözelti 20 °C sıcaklığa kadar soğutulduğunda hangisinin dibinde daha çok katı olur? Nedenleri ile açıklayınız.","c":"Sakkaroz çözeltisinin dibinde daha çok katı olur. Sakkaroz: 288,9 − 201,9 = 87 g çöker. NaCl: 37,1 − 35,7 = 1,4 g çöker. Sakkarozun çözünürlüğü sıcaklıkla çok değişirken NaCl’ninki çok az değişir."}],"ek":[{"q":"20 °C’ta NaCl’nin çözünürlüğü 36 g/100 g sudur. 100 g suya 50 g NaCl eklenirse ne olur?","s":["Hepsi çözünür","36 g çözünür, 14 g dipte kalır","14 g çözünür, 36 g dipte kalır","Hiç çözünmez"],"d":1,"a":"Çözünürlük sınırı 36 g’dır; fazlası çözünmeden kalır ve çözelti doymuş olur."},{"q":"Bu deneyde kontrol değişkeni hangisidir?","s":["Çözünen maddenin cinsi","Sıcaklık ve su miktarı","Dipte kalan katı miktarı","Çözünen katı miktarı"],"d":1,"a":"Farklı maddelerin çözünürlüğünü karşılaştırmak için sıcaklık ve su miktarı sabit tutulur."},{"q":"Çözünürlük neden ayırt edici bir özelliktir?","s":["Her madde için miktardan bağımsız, belirli koşullarda sabit bir değerdir","Bütün maddelerde aynıdır","Yalnızca kütleye bağlıdır","Renkle ilgilidir"],"d":0,"a":"Belirli sıcaklık ve basınçta her saf maddenin çözünürlüğü kendine özgüdür."}]},"cozunurluk2":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 177–178 · MiniLAB ve Kontrol Noktası (MiniLAB’ın kendi sorusu yok, deney raporu isteniyor)","kitap":[{"q":"Endüstride ve reaktörlerde kullanılan suyun nehir ve göllere salınması sonucunda termal kirlenme oluşur. Termal kirlenmenin deniz canlıları üzerindeki etkisini çözünürlük kavramı ile açıklayınız.","c":"Gazların sudaki çözünürlüğü sıcaklık arttıkça azalır. Sıcak su karışan göl ve nehirlerde çözünmüş oksijen miktarı düşer; balıklar ve diğer su canlıları yeterli oksijen bulamaz, ölümler ve tür azalması görülür."},{"q":"Sıcaklık katıların çözünürlüğü için oldukça önemli bir değişkendir. Bu nedenle safsızlık içeren katılar çözünürlük farkından yararlanılarak saflaştırılabilir. %10 safsızlık olarak NaCl içeren 200 g KNO₃ örneğinden saf KNO₃ tuzunu nasıl elde edersiniz? Bir yol haritası oluşturunuz.","c":"Örnek sıcak suda tamamen çözülür (KNO₃’ün çözünürlüğü sıcakta çok yüksektir). Çözelti soğutulur: KNO₃’ün çözünürlüğü hızla düştüğü için kristallenir, NaCl’nin çözünürlüğü sıcaklıkla az değiştiği ve miktarı az olduğu için çözeltide kalır. Kristaller süzülüp kurutulur (ayrımsal kristallendirme)."}],"ek":[{"q":"Gazlı içecek şişesi açıldığında köpürmesinin nedeni hangisidir?","s":["Sıcaklık artar","Basınç azalır, gazın çözünürlüğü düşer","Basınç artar","Şeker çöker"],"d":1,"a":"Gazların çözünürlüğü basınçla doğru orantılıdır. Kapak açılınca basınç düşer, CO₂ çözeltiyi terk eder."},{"q":"Çoğu katının sudaki çözünürlüğü sıcaklık arttıkça nasıl değişir?","s":["Artar","Azalır","Değişmez","Sıfır olur"],"d":0,"a":"Çözünmesi endotermik olan katıların çözünürlüğü sıcaklıkla artar; NaCl’de artış çok azdır, Ce₂(SO₄)₃ gibi bazılarında azalır."}]},"koligatif":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 200 · Değerlendirme","kitap":[{"q":"Saf bir çözücüye eklenen tüm maddeler kaynama noktasını yükseltir mi? Arkadaşlarınızla tartışınız ve tartışma sonucu ulaştığınız ortak fikirleri yazınız.","c":"Hayır. Uçucu olmayan ve çözücüde çözünen maddeler (şeker, tuz) kaynama noktasını yükseltir. Çözünmeyen maddeler (kum) etkilemez. Uçucu maddeler (örneğin alkol) ise çözeltinin kaynama noktasını düşürebilir."},{"q":"Bir çözeltinin kaynama noktasının hangi sıcaklığa kadar yükseleceğini gerekçelerinizle açıklayınız.","c":"Kaynama sırasında çözücü buharlaştıkça çözelti derişikleşir ve kaynama noktası yükselmeye devam eder. Çözelti doymuş hâle geldiğinde derişim artık değişmez; kaynama noktası bu en yüksek değerde sabitlenir."},{"q":"Eşit miktardaki çözücüye eşit mollerde NaCl ve C₆H₁₂O₆ ilave edilirse kaynama noktaları eşit miktarda yükselir mi? Açıklayınız.","c":"Hayır. Koligatif özellikler çözünen tanecik sayısına bağlıdır. NaCl suda Na⁺ ve Cl⁻ iyonlarına ayrışır, 1 mol NaCl 2 mol tanecik verir. Glikoz moleküler çözünür, 1 mol glikoz 1 mol tanecik verir. Bu yüzden NaCl çözeltisinin kaynama noktası yaklaşık iki kat fazla yükselir."}],"ek":[{"q":"Kışın yollara tuz serpilmesinin nedeni nedir?","s":["Buzun donma noktasını yükseltmek","Suyun donma noktasını düşürmek","Yolu ısıtmak","Kar yağışını durdurmak"],"d":1,"a":"Tuzlu suyun donma noktası saf sudan düşüktür; bu yüzden 0 °C’ın altında bile buz oluşmaz ya da erir."},{"q":"Koligatif özellikler neye bağlıdır?","s":["Çözünenin cinsine","Çözünen tanecik sayısına","Çözeltinin rengine","Kabın şekline"],"d":1,"a":"Kaynama noktası yükselmesi ve donma noktası alçalması çözünenin türüne değil, tanecik sayısına bağlıdır."},{"q":"Arabaların radyatör suyuna antifriz (etilen glikol) katılmasının amacı hangisidir?","s":["Suyun donma noktasını düşürmek, kaynama noktasını yükseltmek","Suyu renklendirmek","Suyun yoğunluğunu düşürmek","Motoru soğutmayı durdurmak"],"d":0,"a":"Çözünen tanecikler suyun hem donma noktasını düşürür hem kaynama noktasını yükseltir."}]},"gumusagaci":{"kaynak":"MEB 10. sınıf Kimya ders kitabı, s. 256–257 · 3. Tema Ölçme ve Değerlendirme, 13. ve 14. soru","kitap":[{"q":"Aşağıda makro ölçekte verilen deney planını mikro ölçekli hâle getiriniz. (Makro plan: 10 g AgNO₃, 200 mL saf su, 250 mL’lik beherglas, baget, hassas terazi, bakır tel, spatül; bakır tel yaklaşık yarım saat bekletilir.)","c":"Deneyin adı ve amacı aynı kalır. Araç-gereç: kuyu plakası ya da küçük deney tüpü, damlalık, ince bakır tel parçası, 0,1 M AgNO₃ çözeltisi. Yapılış: kuyuya 1–2 mL AgNO₃ çözeltisi damlatılır, ağaç şekli verilmiş küçük bakır tel içine konur, birkaç dakika beklenir ve büyüteçle gümüş kristalleri gözlenir. Böylece yaklaşık 100 kat daha az gümüş nitrat kullanılır."},{"q":"Aşağıdaki tabloda mikro deneylerin ekosistemle ilişkisi başlıklar hâlinde verilmiştir. Tabloyu uygun şekilde tamamlayınız. (Atom ekonomisi, su ayak izi, karbon ayak izi, sürdürülebilirlik)","c":"Atom ekonomisi: tepkenlerin büyük kısmı ürüne dönüşür, israf edilen madde azalır. Su ayak izi: çözelti hazırlama ve temizlikte çok az su kullanılır. Karbon ayak izi: kimyasal üretimi, taşınması ve atık bertarafı için harcanan enerji azalır. Sürdürülebilirlik: sınırlı kaynaklar (gümüş gibi) korunur, gelecek nesillere kaynak bırakılır."}],"ek":[{"q":"Gümüş ağacı deneyinde bakır telin etrafında oluşan parlak kristaller nedir?","s":["Bakır","Gümüş","Gümüş nitrat","Bakır nitrat"],"d":1,"a":"Cu, Ag⁺ iyonlarına elektron verir; Ag⁺ iyonları indirgenerek metalik gümüş kristallerine dönüşür."},{"q":"Deney ilerledikçe çözeltinin mavileşmesinin nedeni nedir?","s":["Gümüş iyonlarının oluşması","Cu²⁺ iyonlarının çözeltiye geçmesi","Suyun ayrışması","Nitratın çökmesi"],"d":1,"a":"Bakır atomları yükseltgenerek Cu²⁺ iyonu hâlinde çözeltiye geçer; hidratlaşmış Cu²⁺ iyonları maviye boyar."},{"q":"Cu(k) + 2AgNO₃(suda) → Cu(NO₃)₂(suda) + 2Ag(k) tepkimesi hangi tepkime türüdür?","s":["Çökelme","Asit-baz","İndirgenme-yükseltgenme","Yanma"],"d":2,"a":"Bakır elektron verir (yükseltgenir), gümüş iyonu elektron alır (indirgenir)."}]},"isidegisim":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 18 · Değerlendirme","kitap":[{"q":"Deney sonuçlarına göre fiziksel ve kimyasal değişimleri endotermik ve ekzotermik olarak belirleme ölçütünüz nedir?","c":"Ölçüt sıcaklık değişimidir. Olay sırasında çözeltinin (çevrenin) sıcaklığı yükseliyorsa sistem ısı vermiştir, olay ekzotermiktir (NaOH’ın suda çözünmesi). Sıcaklık düşüyorsa sistem çevreden ısı almıştır, olay endotermiktir (NH₄Cl’ün suda çözünmesi)."}],"ek":[{"q":"NH₄Cl suda çözünürken beherin dışına dokunduğumuzda soğuk hissetmemizin nedeni nedir?","s":["Çözünme ekzotermiktir","Çözünme çevreden (elimizden) ısı alır","Su buharlaşır","NH₄Cl tepkimeye girmez"],"d":1,"a":"Endotermik olaylarda sistem çevreden ısı soğurur; çevre (beher ve elimiz) soğur."},{"q":"Hangisi ekzotermik bir olaydır?","s":["Buzun erimesi","Suyun buharlaşması","Odunun yanması","Elektrolizle suyun ayrışması"],"d":2,"a":"Yanma tepkimeleri çevreye ısı verir. Erime, buharlaşma ve elektroliz enerji alır."},{"q":"Ekzotermik bir tepkimede ΔH için hangisi doğrudur?","s":["ΔH > 0","ΔH < 0","ΔH = 0","ΔH ölçülemez"],"d":1,"a":"Sistem ısı verdiği için ürünlerin entalpisi tepkenlerinkinden düşüktür; ΔH negatiftir."}]},"yakit":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 25 · Değerlendirme","kitap":[{"q":"Yanma tepkimesi temelinde seçtiğiniz maddelerin enerji kaynağı olma potansiyelini deney sonuçlarından yola çıkarak açıklayınız.","c":"Aynı kütlede yakılan maddelerden suyun sıcaklığını en çok artıran madde birim kütle başına en çok enerjiyi verir. Deneyde ceviz ve fındık (yağ oranı yüksek) şekerden daha çok ısı verdi. Bu nedenle yağ içeriği yüksek maddelerin enerji kaynağı olma potansiyeli daha yüksektir. Q = m·c·ΔT ile suya aktarılan ısı hesaplanıp yakıtın kütlesine bölünerek karşılaştırma yapılır."}],"ek":[{"q":"100 g suyun sıcaklığı 20 °C artıyorsa suya aktarılan ısı kaç J’dür? (c = 4,18 J/g·°C)","s":["418 J","4 180 J","8 360 J","836 J"],"d":2,"a":"Q = m·c·ΔT = 100 × 4,18 × 20 = 8 360 J."},{"q":"Deneyde ölçülen ısının yanmadaki gerçek ısıdan küçük çıkmasının en önemli nedeni nedir?","s":["Suyun fazla olması","Isının bir kısmının havaya ve kaba kaçması","Termometrenin büyük olması","Yakıtın hızlı yanması"],"d":1,"a":"Açık düzenekte ısının bir kısmı çevreye kaybolur; ölçülen değer gerçek yanma ısısından küçüktür."},{"q":"Birim kütle başına en çok ısı veren yakıt hangisidir?","s":["Odun","Taş kömürü","Doğal gaz","Hidrojen gazı"],"d":3,"a":"Hidrojen gazının yanma ısısı yaklaşık 143 kJ/g’dır; doğal gazın yaklaşık üç katıdır."}]},"hiz_madde":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 73 · Değerlendirme","kitap":[{"q":"Gerçekleştirdiğiniz deneyde madde cinsinin tepkime hızına etkisine ilişkin neler gözlemlediniz?","c":"Aynı derişimdeki HCl ile en hızlı Mg, sonra Zn, en yavaş Fe tepkimeye girdi; Cu hiç tepkime vermedi. Gaz kabarcıklarının çıkış hızı ve balonun şişme süresi metalin cinsine göre değişti."},{"q":"Hipotezinize ilişkin belirlediğiniz bağımlı-bağımsız değişkenler ve kontrol değişkenleri ile gerçekleştirdiğiniz deneydeki değişkenlerin doğruluğunu karşılaştırınız.","c":"Bağımsız değişken metalin cinsi, bağımlı değişken H₂ gazının oluşma hızı (balonun şişme süresi ya da kabarcık hızı), kontrol değişkenleri ise HCl’nin derişimi ve hacmi, metalin kütlesi ve yüzeyi, sıcaklıktır. Deneyde yalnızca metal değiştirildiği için değişkenler doğru belirlenmiştir."},{"q":"Deney sonucunda hipotezinizin doğruluğunu kontrol ederek hipotezinizi yorumlayınız.","c":"“Metalin aktifliği arttıkça tepkime hızı artar.” hipotezi doğrulandı: hız Mg > Zn > Fe sırasında, Cu ise asitle tepkime vermedi."}],"ek":[{"q":"Cu metali seyreltik HCl ile neden tepkime vermez?","s":["Bakır çok aktiftir","Bakır hidrojenden daha az aktiftir","Bakır asitte çözünür","Bakır gazdır"],"d":1,"a":"Aktiflik sırasında hidrojenin altında olan bakır, asitteki H⁺ iyonlarını indirgeyemez."},{"q":"Tepkenlerinde kırılan bağ sayısı fazla olan bir tepkimenin hızı için ne söylenebilir?","s":["Genellikle daha yavaştır","Genellikle daha hızlıdır","Hız değişmez","Tepkime gerçekleşmez"],"d":0,"a":"Daha çok bağın kırılması gerektiğinde tepkime genellikle daha yavaş gerçekleşir (C₃H₈ yanması CH₄’ten yavaştır)."}]},"hiz_hal":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 75 · Değerlendirme","kitap":[{"q":"Gerçekleştirdiğiniz deneyde maddenin fiziksel hâlinin tepkime hızına etkisine ilişkin neler gözlemlediniz?","c":"Magnezyum kaynar su ile çok yavaş tepkime verdi, su buharı ile ise parlak bir ışık çıkararak hızla tepkimeye girdi. Aynı maddenin gaz hâli sıvı hâline göre daha hızlı tepkime verdi."},{"q":"Hipotezinize ilişkin belirlediğiniz bağımlı-bağımsız değişkenler ve kontrol değişkenleri ile gerçekleştirdiğiniz deneydeki değişkenlerin doğruluğunu karşılaştırınız.","c":"Bağımsız değişken suyun fiziksel hâli (sıvı/gaz), bağımlı değişken tepkime hızı (gözlenen tepkimenin şiddeti ve süresi), kontrol değişkenleri magnezyumun kütlesi ve yüzeyi ile sıcaklıktır."},{"q":"Deney sonucunda hipotezinizin doğruluğunu kontrol ederek hipotezinizi yorumlayınız.","c":"“Tepkenlerin gaz hâlde olması tepkime hızını artırır.” hipotezi doğrulandı: gaz hâldeki taneciklerin hareketliliği ve çarpışma olasılığı daha yüksektir."}],"ek":[{"q":"Genel olarak hangi fiziksel hâlde gerçekleşen tepkimeler en hızlıdır?","s":["Katı-katı","Sıvı-katı","Gaz-gaz","Hepsi eşit"],"d":2,"a":"Gaz taneciklerinin hareketliliği en yüksektir; çarpışma olasılığı ve dolayısıyla hız en büyüktür."},{"q":"Çözeltideki iyonlar arasında gerçekleşen tepkimelerin çok hızlı olmasının nedeni nedir?","s":["İyonlar serbest hareket eder ve bağ kırılması gerekmez","İyonlar katıdır","İyonların kütlesi büyüktür","Çözücü tepkimeyi engeller"],"d":0,"a":"Zıt yüklü iyonlar birbirini çeker ve kırılması gereken bir bağ olmadan hemen birleşebilir (örneğin Ag⁺ + Cl⁻)."}]},"hiz_derisim":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 77 · Değerlendirme","kitap":[{"q":"Gerçekleştirdiğiniz deneyde derişimin tepkime hızına etkisine ilişkin neler gözlemlediniz?","c":"HCl derişimi arttıkça çinkonun yüzeyinden çıkan gaz kabarcıkları arttı ve balon daha kısa sürede şişti. 2 M HCl ile tepkime en hızlı, 0,5 M HCl ile en yavaş oldu."},{"q":"Hipotezinize ilişkin belirlediğiniz bağımlı-bağımsız değişkenler ve kontrol değişkenleri ile gerçekleştirdiğiniz deneydeki değişkenlerin doğruluğunu karşılaştırınız.","c":"Bağımsız değişken HCl’nin derişimi, bağımlı değişken H₂ gazının oluşma hızı (balonun şişme süresi), kontrol değişkenleri çinkonun kütlesi ve yüzeyi, asidin hacmi ve sıcaklıktır."},{"q":"Deney sonucunda hipotezinizin doğruluğunu kontrol ederek yorumlayınız.","c":"“Tepken derişimi arttıkça tepkime hızı artar.” hipotezi doğrulandı: birim hacimdeki tanecik sayısı arttıkça etkin çarpışma sayısı artar."}],"ek":[{"q":"Derişimin artması aktivasyon enerjisini nasıl etkiler?","s":["Artırır","Azaltır","Değiştirmez","Sıfırlar"],"d":2,"a":"Derişim yalnızca çarpışma sayısını artırır; aktivasyon enerjisi değişmez."},{"q":"Gaz fazındaki bir tepkimede kabın hacmi küçültülürse tepkime hızı ne olur?","s":["Artar","Azalır","Değişmez","Durur"],"d":0,"a":"Hacim küçülünce gazların derişimi artar, çarpışmalar sıklaşır ve tepkime hızlanır."}]},"hiz_sicaklik":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 80 · Değerlendirme","kitap":[{"q":"Gerçekleştirdiğiniz deneyde sıcaklığın tepkime hızına etkisine ilişkin neler gözlemlediniz?","c":"50 °C’taki HCl çözeltisinde demir 10 °C’takine göre çok daha hızlı tepkime verdi; gaz kabarcıkları daha yoğun çıktı ve balon daha kısa sürede şişti."},{"q":"Hipotezinize ilişkin belirlediğiniz bağımlı-bağımsız değişkenleri ve kontrol değişkenleri ile gerçekleştirdiğiniz deneydeki değişkenlerin doğruluğunu karşılaştırınız.","c":"Bağımsız değişken sıcaklık, bağımlı değişken H₂ gazının oluşma hızı, kontrol değişkenleri demirin kütlesi ve yüzeyi, HCl’nin derişimi ve hacmidir."},{"q":"Deney sonucunda hipotezinizin doğruluğunu kontrol ederek yorumlayınız.","c":"“Sıcaklık arttıkça tepkime hızı artar.” hipotezi doğrulandı: sıcaklık artınca kinetik enerjisi eşik enerjisini aşan tanecik sayısı artar."}],"ek":[{"q":"Sıcaklık artışı tepkime hızını hangi yolla artırır?","s":["Aktivasyon enerjisini düşürerek","Eşik enerjisini aşan tanecik sayısını artırarak","Tepken derişimini artırarak","Ürünlerin enerjisini artırarak"],"d":1,"a":"Sıcaklık aktivasyon enerjisini değiştirmez; yeterli enerjiye sahip tanecik sayısını artırır."},{"q":"Yiyecekleri buzdolabında saklamanın nedeni hangisidir?","s":["Bozulma tepkimelerini yavaşlatmak","Tepkimeleri hızlandırmak","Katalizör eklemek","Derişimi artırmak"],"d":0,"a":"Düşük sıcaklıkta bozulmaya yol açan tepkimeler ve mikroorganizma etkinliği yavaşlar."}]},"hiz_katalizor":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 83 · Değerlendirme","kitap":[{"q":"Gerçekleştirdiğiniz deneyde katalizörün tepkime hızına etkisine ilişkin neler gözlemlediniz?","c":"MnO₂ eklenen H₂O₂ çözeltisinde yoğun köpürme ve hızlı gaz (O₂) çıkışı oldu; kor hâlindeki kıymık alevlendi. MnO₂ eklenmeyen tüpte ayrışma çok yavaştı. Tepkime sonunda MnO₂ dipte değişmeden kaldı."},{"q":"Hipotezinize ilişkin belirlediğiniz bağımlı-bağımsız değişkenleri ve kontrol değişkenleri ile gerçekleştirdiğiniz deneydeki değişkenlerin doğruluğunu karşılaştırınız.","c":"Bağımsız değişken katalizörün (MnO₂) varlığı, bağımlı değişken O₂ gazının oluşma hızı, kontrol değişkenleri H₂O₂’nin derişimi ve hacmi ile sıcaklıktır."},{"q":"Deney sonucunda hipotezinizin doğruluğunu kontrol ederek yorumlayınız.","c":"“Katalizör tepkime hızını artırır.” hipotezi doğrulandı: katalizör aktivasyon enerjisi daha düşük olan yeni bir yol sağlar."}],"ek":[{"q":"Katalizör için hangisi yanlıştır?","s":["Aktivasyon enerjisini düşürür","Tepkime sonunda değişmeden çıkar","Tepkimenin ΔH değerini değiştirir","Tepkimeyi hızlandırır"],"d":2,"a":"Katalizör tepken ve ürünlerin enerjisini değiştirmez; ΔH aynı kalır."},{"q":"Kor hâlindeki kıymığın alevlenmesi hangi gazın varlığını gösterir?","s":["H₂","CO₂","O₂","N₂"],"d":2,"a":"Oksijen yanmayı destekler; kor hâlindeki kıymık oksijenli ortamda alev alır."}]},"hiz_yuzey":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 86 · Değerlendirme","kitap":[{"q":"Gerçekleştirdiğiniz deneyde temas yüzeyinin tepkime hızına etkisine ilişkin neler gözlemlediniz?","c":"Aynı kütlede magnezyum kullanıldığında toz magnezyum en hızlı, şerit magnezyum en yavaş tepkime verdi. Temas yüzeyi arttıkça gaz çıkışı hızlandı; tepkime sonunda oluşan toplam gaz miktarı ise aynıydı."},{"q":"Hipotezinize ilişkin belirlediğiniz bağımlı-bağımsız değişkenleri ve kontrol değişkenleri ile gerçekleştirdiğiniz deneydeki değişkenlerin doğruluğunu karşılaştırınız.","c":"Bağımsız değişken magnezyumun temas yüzeyi (şerit, parça, toz), bağımlı değişken H₂ gazının oluşma hızı, kontrol değişkenleri magnezyumun kütlesi, HCl’nin derişimi ve hacmi, sıcaklıktır."},{"q":"Deney sonucunda hipotezinizin doğruluğunu kontrol ederek yorumlayınız.","c":"“Temas yüzeyi arttıkça tepkime hızı artar.” hipotezi doğrulandı: toz hâlinde daha çok tanecik aynı anda asitle çarpışabilir."}],"ek":[{"q":"Toz ve parça çinkonun aynı kütlelerinin aynı asitle tepkimesinde hangisi aynıdır?","s":["Tepkime süresi","Oluşan toplam H₂ miktarı","Tepkime hızı","Kabarcık sayısı"],"d":1,"a":"Yüzey yalnızca hızı değiştirir; aynı miktar madde aynı miktar ürün verir."},{"q":"Un fabrikalarında ve maden ocaklarında toz patlamalarının olmasının nedeni hangisidir?","s":["Tozların temas yüzeyinin çok büyük olması","Tozların ağır olması","Ortamın soğuk olması","Tozların yanmaz olması"],"d":0,"a":"Havada dağılmış ince tozların oksijenle temas yüzeyi çok büyüktür; yanma bir anda gerçekleşebilir."}]},"hiz_tum":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 88 · 1.7. Kontrol Noktası (performans görevi öğretmen tarafından değerlendirilir)","giris":"Aşağıdaki tabloda verilen ifadeler doğruysa “D”, yanlışsa “Y” yazarak cevabınızı belirtiniz. İfade yanlış ise nedenini “Açıklamalar” kısmına yazınız.","kitap":[{"q":"“Katı yakıtlar sıvı yakıtlara göre neden daha yavaş yanar?” sorusu sıcaklığın tepkime hızına etkisiyle ilgili araştırılabilir bir sorudur.","dy":"Y","c":"Yanlış. Bu soru maddenin fiziksel hâlinin (ve temas yüzeyinin) tepkime hızına etkisiyle ilgilidir."},{"q":"“Temas yüzeyinin artması tepkimenin hızını artırır.” şeklinde oluşturulan bir hipotezin bilimsel bilgilerle geçerliliği doğrulanabilir.","dy":"D","c":"Doğru. Hipotez deneyle test edilebilir ve bilimsel bilgilerle (çarpışma teorisi) desteklenir."},{"q":"“Kalsiyumun farklı sıcaklıklardaki su ile verdiği tepkimeleri gözlemlemek için planlanan bir deney” tepkime hızına katalizörün etkisini açıklayan bir deney planlamasıdır.","dy":"Y","c":"Yanlış. Bu deneyde değiştirilen değişken sıcaklıktır; deney sıcaklığın etkisini açıklar."},{"q":"“Deney verilerine göre H₂O₂ ayrışma tepkimesinin bromlu suda daha kısa sürede gerçekleştiği tespit edilmiştir.” bu veri analizinden katalizörün tepkime hızını artırdığı yorumu yapılabilir.","dy":"D","c":"Doğru. Bromlu su H₂O₂’nin ayrışmasında katalizör görevi görür; tepkime daha kısa sürede tamamlanır."},{"q":"Sıcaklık, tepken taneciklerinin kinetik enerjisini artırdığı için etkin çarpışma sayısını artırır.","dy":"D","c":"Doğru."},{"q":"Katalizör, aktivasyon enerjisini artırarak tepkimeyi hızlandırır.","dy":"Y","c":"Yanlış. Katalizör aktivasyon enerjisini düşürerek tepkimeyi hızlandırır."}],"ek":[{"q":"Zn + HCl tepkimesini en hızlı hâle getirmek için hangi koşullar seçilmelidir?","s":["Parça Zn, 0,5 M HCl, 10 °C","Toz Zn, 2 M HCl, 50 °C","Parça Zn, 2 M HCl, 10 °C","Toz Zn, 0,5 M HCl, 10 °C"],"d":1,"a":"Temas yüzeyi, derişim ve sıcaklığın üçü de en yüksek olduğunda tepkime en hızlıdır."},{"q":"Bir deneyde aynı anda iki değişken değiştirilirse ne olur?","s":["Sonuç daha güvenilir olur","Hangi değişkenin etkili olduğu anlaşılamaz","Tepkime durur","Kontrol değişkeni artar"],"d":1,"a":"Bilimsel deneylerde her seferinde yalnız bir bağımsız değişken değiştirilir."}]},"kromat":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 126 · Değerlendirme","kitap":[{"q":"Bir tepkimenin tersinir olduğuna kanıt olacak gözlemlenebilir nitelikler nelerdir? Açıklayınız.","c":"Renk değişiminin geri dönmesi en belirgin kanıttır. Sarı kromat (CrO₄²⁻) çözeltisine asit eklenince turuncu dikromat (Cr₂O₇²⁻) oluştu; ardından baz eklenince renk yeniden sarıya döndü. Ürünlerin yeniden tepkenlere dönüşebilmesi tepkimenin her iki yönde de ilerleyebildiğini gösterir."},{"q":"Tepkimelerin tersinir olabileceğine ilişkin tespitleriniz nelerdir?","c":"2CrO₄²⁻ + 2H⁺ ⇌ Cr₂O₇²⁻ + H₂O tepkimesi ileri yönde (H⁺ eklenince) ve geri yönde (OH⁻ eklenip H⁺ azaltılınca) ilerleyebilir. Koşullar değiştirildiğinde tepkime yön değiştirebiliyorsa tersinirdir. Kapalı sistemde ileri ve geri tepkime hızları eşitlendiğinde denge kurulur."}],"ek":[{"q":"Kromat-dikromat dengesinde ortama H⁺ eklenirse renk nasıl değişir?","s":["Sarıdan turuncuya","Turuncudan sarıya","Renksizleşir","Maviye döner"],"d":0,"a":"H⁺ derişiminin artması dengeyi dikromat (turuncu) yönüne kaydırır."},{"q":"Hangisi tersinir bir olaya örnektir?","s":["Kâğıdın yanması","Kapalı kapta suyun buharlaşıp yoğuşması","Yumurtanın pişmesi","Demirin paslanması"],"d":1,"a":"Kapalı kapta buharlaşma ve yoğuşma aynı anda gerçekleşir; olay iki yönde de ilerler."},{"q":"Denge anında ileri ve geri tepkime için hangisi doğrudur?","s":["İkisi de durmuştur","Hızları eşittir","İleri tepkime daha hızlıdır","Geri tepkime durmuştur"],"d":1,"a":"Denge dinamiktir; iki tepkime de devam eder ama hızları eşit olduğu için derişimler sabit kalır."}]},"kuvvet":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 200 · Değerlendirme","kitap":[{"q":"Asitlerin ve bazların kuvvetini belirleyen ölçüt nedir?","c":"Suda iyonlaşma oranıdır. Aynı derişimde suda tamamen iyonlaşan HCl ve NaOH kuvvetlidir: pH değerleri uç değerlerdedir (HCl’de pH ≈ 1, NaOH’ta pH ≈ 13) ve iletkenlikleri yüksektir. Kısmen iyonlaşan CH₃COOH ve NH₃ zayıftır: pH değerleri 7’ye daha yakındır, iletkenlikleri düşüktür."}],"ek":[{"q":"0,1 M HCl ve 0,1 M CH₃COOH çözeltilerinden hangisinin iletkenliği daha yüksektir?","s":["CH₃COOH","HCl","Eşittir","İkisi de iletmez"],"d":1,"a":"HCl tamamen iyonlaşır, çözeltide çok daha fazla iyon bulunur."},{"q":"Zayıf bir asidin suda iyonlaşması için hangisi doğrudur?","s":["Tek yönlüdür, tamamen gerçekleşir","Tersinirdir, kısmen gerçekleşir","Hiç gerçekleşmez","Yalnızca ısıtılınca olur"],"d":1,"a":"Zayıf asitlerin iyonlaşması dengeye ulaşan tersinir bir olaydır; asit moleküllerinin çoğu iyonlaşmadan kalır."},{"q":"Asit kuvveti ile asit derişimi aynı kavram mıdır?","s":["Evet, aynıdır","Hayır; kuvvet iyonlaşma oranı, derişim birim hacimdeki miktardır","Evet, ikisi de pH’tır","Hayır; kuvvet kütleye bağlıdır"],"d":1,"a":"Derişik bir zayıf asit, seyreltik bir kuvvetli asitten daha düşük pH gösterebilir; ama yine de zayıf asittir."}]},"notrallesme":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 225 · Değerlendirme","kitap":[{"q":"Nötralleşme tepkimelerini gözlemleyebilmek için hangi ölçütler kullanılabilir?","c":"pH değişimi (pH metre ya da pH kâğıdı ile; tam nötralleşmede 25 °C’ta pH = 7), indikatörün renk değişimi (fenolftaleinin pembeleşmesi, metil oranjın renk değiştirmesi), iletkenlik değişimi (eşdeğerlik noktasına kadar azalır, sonra artar) ve sıcaklık artışı."},{"q":"Nötralleşme olayını hidrojen ve hidroksit iyonlarının mol sayıları arasındaki matematiksel ilişkiyi kullanarak tanımlayınız.","c":"Nötralleşmede H⁺ + OH⁻ → H₂O tepkimesine göre iyonlar 1:1 oranında birleşir. n(H⁺) = n(OH⁻) ise tam nötralleşme olur ve çözelti nötrdür. n(H⁺) > n(OH⁻) ise çözelti asidik, n(H⁺) < n(OH⁻) ise baziktir (kısmi nötralleşme)."}],"ek":[{"q":"40 mL 0,1 M HCl’yi tam nötrleştirmek için kaç mL 0,1 M NaOH gerekir?","s":["20 mL","40 mL","80 mL","4 mL"],"d":1,"a":"n(H⁺) = 0,1 × 0,040 = 0,004 mol. Aynı derişimdeki NaOH’tan 0,004 mol için 40 mL gerekir."},{"q":"Nötralleşme sırasında iletkenliğin önce azalmasının nedeni nedir?","s":["H⁺ iyonları daha yavaş hareket eden Na⁺ iyonlarıyla yer değiştirir","Çözelti buharlaşır","Tuz çöker","Sıcaklık düşer"],"d":0,"a":"Çok hareketli H⁺ iyonları su oluşturarak ortadan kalkar, yerine daha az hareketli Na⁺ gelir; eşdeğerlikten sonra fazla OH⁻ iletkenliği yeniden artırır."},{"q":"100 mL 1 M HCl ile 100 mL 0,8 M NaOH karıştırılırsa çözelti için hangisi doğrudur?","s":["Nötrdür","Asidiktir","Baziktir","Tuz çöker"],"d":1,"a":"n(H⁺) = 0,1 mol, n(OH⁻) = 0,08 mol. H⁺ arttığı için çözelti asidiktir."}]},"titrasyon":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 235 · Değerlendirme","kitap":[{"q":"Titrasyon işleminde derişimi bilinmeyen kuvvetli asit ya da kuvvetli baz çözeltisinin derişimini belirlemek için hangi ölçütlerden yararlanılır?","c":"Dönüm noktasından yararlanılır: indikatörün kalıcı renk değişimi (fenolftaleinin kalıcı pembeleşmesi), pH metrede pH’ın 7 civarında ani sıçraması ya da iletkenliğin en düşük değere inmesi. Bu noktaya kadar harcanan büret hacmi okunur."},{"q":"Titrasyon işleminde derişimi bilinmeyen kuvvetli bir asit ya da kuvvetli bazın derişimi nasıl hesaplanır? Açıklayınız.","c":"Dönüm noktasında n(H⁺) = n(OH⁻) olur. Monofonksiyonel asit ve bazlar için Masit·Vasit = Mbaz·Vbaz eşitliği kullanılır. Örneğin 25 mL HCl için 0,1 M NaOH’tan 20 mL harcandıysa M(HCl) = 0,1 × 20 / 25 = 0,08 M bulunur."}],"ek":[{"q":"Titrasyonda büretteki çözelti için hangisi doğrudur?","s":["Derişimi bilinmeyen çözeltidir","Derişimi bilinen (standart) çözeltidir","İndikatördür","Saf sudur"],"d":1,"a":"Bürete derişimi bilinen çözelti konur ve damla damla erlenmayerdeki çözeltiye eklenir."},{"q":"Kuvvetli asit-kuvvetli baz titrasyonunda eşdeğerlik noktasında pH kaçtır (25 °C)?","s":["1","5","7","13"],"d":2,"a":"Tam nötralleşmede çözeltide yalnız suyun iyonlaşmasından gelen H⁺ ve OH⁻ bulunur; pH = 7."},{"q":"Eşdeğerlik noktası ile dönüm noktası arasındaki fark nedir?","s":["Aynı şeydir","Eşdeğerlik teorik, dönüm noktası gözlenen (renk değişimi) noktadır","Dönüm noktası teoriktir","Eşdeğerlik noktası renk değişimidir"],"d":1,"a":"Eşdeğerlik noktası doğrudan gözlenemez; hesaplarda indikatörün renk değiştirdiği dönüm noktası kullanılır."}]},"urunph":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 241 · Değerlendirme","kitap":[{"q":"Asidik ve bazik özellik gösteren mide, ağız, diş ve cilt sağlığı için kullanılan ürünlerden en uygun olanına hangi ölçüte göre karar verirsiniz?","c":"Ürünün pH değerinin kullanıldığı bölgenin doğal pH değerine uygunluğuna göre. Cilt hafif asidiktir (pH ≈ 4,5–5,5), bu yüzden pH’ı buna yakın ürünler; ağız ve diş için pH’ı nötr ya da hafif bazik ürünler; mide asidi için doktor kontrolünde bazik antiasitler uygundur."},{"q":"Asidik ve bazik özellik gösteren mide, ağız, diş ve cilt sağlığı için kullanılan ürünlerden en uygun olanı seçebilmenin sağlık açısından önemi nedir?","c":"Uygun olmayan pH; ciltte kuruma, tahriş ve koruyucu tabakanın bozulmasına, dişte mine aşınması ve çürüğe, midede reflü, ülser ya da sindirim sorunlarına yol açabilir. Doğru seçim, vücudun doğal pH dengesini ve savunma işlevlerini korur."}],"ek":[{"q":"Sağlıklı insan cildinin pH değeri yaklaşık hangi aralıktadır?","s":["1,5–3,5","4,5–5,5","7,0–7,5","9–11"],"d":1,"a":"Cilt hafif asidiktir; bu “asit örtüsü” bakterilere karşı koruma sağlar."},{"q":"Diş çürüğüne asıl neden olan nedir?","s":["Tükürüğün bazik olması","Bakterilerin şekeri aside dönüştürmesi","Diş macunundaki florür","Suyun nötr olması"],"d":1,"a":"Bakterilerin ürettiği asit diş minesinden mineral çözerek çürüğe yol açar."},{"q":"Mide sıvısının pH değeri genellikle hangi aralıktadır?","s":["1,5–3,5","5–6","7","8–9"],"d":0,"a":"Midede salgılanan HCl nedeniyle mide sıvısı çok asidiktir."}]},"kcc":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 255 · Değerlendirme","kitap":[{"q":"Suda az çözünen tuzların çözünürlüğüne etki eden faktörleri açıklayınız.","c":"Sıcaklık ve ortak iyon. Çözünmesi endotermik olan tuzların çözünürlüğü sıcaklıkla artar; ekzotermik olanlarınki (Ca(OH)₂, Li₂CO₃) azalır. Çözeltide tuzla ortak bir iyon bulunursa (örneğin Ca(OH)₂ için NaOH’tan gelen OH⁻) tuzun çözünürlüğü azalır."},{"q":"Suda az çözünen tuzların çözünürlüğüne etki eden faktörleri Le Chatelier ilkesi ile ilişkilendirerek açıklayınız.","c":"Dengedeki doymuş çözeltiye dışarıdan yapılan etkiyi sistem azaltmaya çalışır. Ekzotermik çözünmede ısıtılınca denge çökelme yönüne kayar, çözünürlük ve Kçç azalır; endotermikte tersi olur. Ortak iyon eklenince sistem bu iyonu azaltmak için çökelme yönüne kayar, çözünürlük azalır ama Kçç sıcaklık değişmedikçe sabit kalır."}],"ek":[{"q":"Ca(OH)₂’in (kireç suyu) çözünmesi ekzotermiktir. Doymuş kireç suyu ısıtılırsa ne gözlenir?","s":["Daha çok katı çözünür","Bulanıklık (çökelme) oluşur","Renk maviye döner","Hiçbir şey değişmez"],"d":1,"a":"Ekzotermik çözünmede sıcaklık artışı dengeyi çökelme yönüne kaydırır; çözünürlük azalır."},{"q":"Ortak iyon eklenmesi Kçç değerini nasıl etkiler (sabit sıcaklıkta)?","s":["Artırır","Azaltır","Değiştirmez","Sıfırlar"],"d":2,"a":"Kçç yalnızca sıcaklığa bağlıdır; ortak iyon çözünürlüğü azaltır ama Kçç’yi değiştirmez."},{"q":"AgCl’nin çözünürlüğü hangi ortamda en azdır?","s":["Saf su","0,01 M NaCl","0,1 M NaCl","0,001 M NaCl"],"d":2,"a":"Ortak iyonun (Cl⁻) derişimi en büyük olan ortamda çözünürlük en küçüktür."}]},"yesilh2":{"kaynak":"MEB 11. sınıf Kimya ders kitabı, s. 296 · 3.1. Kontrol Noktası (performans görevi öğretmen tarafından değerlendirilir)","giris":"Evsel atıklardan hidrojen üreten bir tesiste aynı şartlarda, aynı tür ve eşit miktarda atıkla 4 farklı bakteri türü denenmiştir. Günlük üretilen hidrojen gazı hacmi (m³): A bakterisi 25,6 · B bakterisi 30,5 · C bakterisi 17,4 · Ç bakterisi 35,2.","kitap":[{"q":"Kimya mühendisinin yaptığı deneyin araştırma sorusu ne olabilir?","c":"“Bakteri türü, evsel atıklardan fermantasyonla üretilen hidrojen gazı miktarını nasıl etkiler?”"},{"q":"Deneydeki neden-sonuç ilişkisini yazınız.","c":"Neden: kullanılan bakteri türünün farklı olması. Sonuç: günlük üretilen hidrojen gazı hacminin farklı olması."},{"q":"Deneydeki bağımlı-bağımsız değişkenleri ve kontrol değişkenlerini yazınız.","c":"Bağımlı değişken: günlük üretilen hidrojen gazı hacmi. Bağımsız değişken: bakteri türü. Kontrol değişkenleri: atık türü ve miktarı, sıcaklık, pH, tank hacmi, süre."},{"q":"Deney sonuçlarına göre hidrojen gazı üretimini artırmak için ne yapılmalıdır?","c":"En çok hidrojen üreten “Ç” bakterisi (35,2 m³) kullanılmalıdır."},{"q":"Kimya mühendisinin yerinde olsaydınız üretilen hidrojen miktarını artırmak için mühendisten farklı olarak nasıl bir deney yapardınız?","c":"Bakteri türünü (Ç) sabit tutup başka bir değişkeni değiştirirdim: örneğin sıcaklığı (25, 35, 45 °C), atık miktarını ya da ortamın pH’ını değiştirerek hidrojen hacmini ölçerdim. Her denemede yalnız bir değişken değiştirilmelidir."},{"q":"Günlük üretilen hidrojen gazı miktarını artırmak için uygun bakteri türü kullanmak dışında neler yapılabilir?","c":"Bakterinin en verimli çalıştığı sıcaklık ve pH sağlanabilir, atık miktarı uygun düzeye artırılabilir, atıklar küçük parçalara ayrılarak temas yüzeyi büyütülebilir, ortam karıştırılabilir ve oksijensiz (anaerobik) koşullar korunabilir."}],"ek":[{"q":"Fermantasyonla hidrojen üretimi neden “yeşil hidrojen” olarak kabul edilir?","s":["Fosil yakıt kullanılmadan, atıktan üretildiği için","Hidrojen yeşil renkli olduğu için","Çok pahalı olduğu için","CO₂ üretmediği için hiç atık oluşmadığından"],"d":0,"a":"Yenilenebilir kaynaklardan (evsel atık, biyokütle) fosil yakıt kullanmadan üretilen hidrojen sürdürülebilirdir."},{"q":"Hidrojen gazının yanması sonucu hangi ürün oluşur?","s":["CO₂","Yalnızca H₂O","CO","CH₄"],"d":1,"a":"H₂ + ½O₂ → H₂O; sera gazı olan CO₂ oluşmaz."}]}};
const CSS=`.ks-src{font-size:13px;color:#64748b;margin:-4px 0 10px}.ks-giris{background:#f1f5f9;border-radius:10px;padding:8px 10px;font-size:14px;margin-bottom:10px}
.ks-q{border-top:1px solid #e2e8f0;padding:10px 0}.ks-q p{margin:0 0 6px;font-weight:700}
.ks-q textarea{width:100%;box-sizing:border-box;min-height:60px;border:1.5px solid #cbd5e1;border-radius:10px;padding:8px;font:inherit;font-size:14px;resize:vertical}
.ks-row{display:flex;gap:8px;align-items:center;margin-top:6px;flex-wrap:wrap}.ks-b{border:1.5px solid #cbd5e1;background:#fff;border-radius:999px;padding:5px 14px;font:inherit;font-weight:700;cursor:pointer}
.ks-b:hover{background:#f1f5f9}.ks-b.ok{background:#dcfce7;border-color:#16a34a}.ks-b.no{background:#fee2e2;border-color:#dc2626}
.ks-ans{margin-top:8px;background:#eff6ff;border-left:4px solid #2563eb;border-radius:8px;padding:8px 10px;font-size:14px}.ks-ans b{color:#1d4ed8}
.ks-h{margin-top:16px}`;
function esc(s){return String(s).replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));}
function mount(box,ad,onChange){const v=D[ad];if(!v||!box)return null;
  if(!document.getElementById('ks-css')){const st=document.createElement('style');st.id='ks-css';st.textContent=CSS;document.head.appendChild(st);}
  const cev=v.kitap.map(()=>'');const fire=()=>{try{onChange&&onChange()}catch(e){}};
  let h=`<h2>📘 Kitabın soruları</h2><p class="ks-src">${esc(v.kaynak)}</p>`+(v.giris?`<div class="ks-giris">${esc(v.giris)}</div>`:'');
  h+=v.kitap.map((k,i)=>`<div class="ks-q" data-i="${i}"><p>${i+1}. ${esc(k.q)}</p>`+(k.dy?
     `<div class="ks-row"><button class="ks-b" data-dy="D">D (Doğru)</button><button class="ks-b" data-dy="Y">Y (Yanlış)</button></div>`:
     `<textarea placeholder="Cevabını buraya yaz…"></textarea><div class="ks-row"><button class="ks-b ks-show">👀 Cevabı gör</button></div>`)+`</div>`).join('');
  if(v.ek&&v.ek.length)h+=`<h2 class="ks-h">➕ Ek sorular</h2>`+v.ek.map((e,i)=>`<div class="q ks-mc" data-i="${i}"><p>${i+1}. ${esc(e.q)}</p>${e.s.map((s,j)=>`<button data-j="${j}">${String.fromCharCode(65+j)}) ${esc(s)}</button>`).join('')}</div>`).join('');
  box.innerHTML=h;
  box.querySelectorAll('.ks-q').forEach(q=>{const i=+q.dataset.i,k=v.kitap[i];
    const show=(pre)=>{if(q.querySelector('.ks-ans'))return;const a=document.createElement('div');a.className='ks-ans';a.innerHTML=(pre||'<b>Örnek cevap:</b> ')+esc(k.c);q.append(a);};
    const ta=q.querySelector('textarea');if(ta)ta.oninput=()=>{cev[i]=ta.value.trim();fire();};
    const sb=q.querySelector('.ks-show');if(sb)sb.onclick=()=>{show();sb.disabled=true;};
    q.querySelectorAll('[data-dy]').forEach(b=>b.onclick=()=>{if(q.dataset.done)return;q.dataset.done=1;const ok=b.dataset.dy===k.dy;b.classList.add(ok?'ok':'no');
      q.querySelector(`[data-dy="${k.dy}"]`).classList.add('ok');cev[i]=b.dataset.dy+(ok?' ✓':' ✗');const ad=k.dy==='D'?'D (Doğru)':'Y (Yanlış)';const c0=k.c.replace(/^(Doğru|Yanlış)\.\s*/,'');
      if(!q.querySelector('.ks-ans')){const a=document.createElement('div');a.className='ks-ans';a.innerHTML=(ok?'<b>✅ Bildin! Cevap '+ad+'.</b> ':'<b>❌ Cevap '+ad+'.</b> ')+esc(c0);q.append(a);}fire();});});
  box.querySelectorAll('.ks-mc').forEach(d=>{const e=v.ek[+d.dataset.i];d.querySelectorAll('button').forEach(b=>b.onclick=()=>{if(d.dataset.done)return;d.dataset.done=1;const j=+b.dataset.j;
    b.classList.add(j===e.d?'ok':'no');d.querySelectorAll('button')[e.d].classList.add('ok');const x=document.createElement('div');x.className='ex';x.textContent=(j===e.d?'✅ Doğru. ':'❌ Doğru cevap '+String.fromCharCode(65+e.d)+'. ')+e.a;d.append(x);});});
  return {rows:()=>{const L=v.kitap.map((k,i)=>cev[i]?`${i+1}) ${esc(k.q)}<br>→ ${esc(cev[i])}`:'').filter(Boolean);return L.length?[['Değerlendirme (kitabın soruları)',L.join('<br>')]]:[];}};}
window.KS={D,mount};
})();
